#!/usr/bin/env bash
# Plays a computer-only game in C 1oom and keeps a save of every year.
# Usage: tools/harness/run-1oom.sh LBXDIR OUTDIR YEARS [NEWGAME] [AI]
#   LBXDIR   MOO1 data files (RESEARCH.LBX is generated by aoo-harness if missing)
#   OUTDIR   receives 1oom_save_YYYY.bin
#   YEARS    turns to play (1oom year counter: 1 = 2300)
#   NEWGAME  1oom -new argument, OPT:RACES:BANNERS:GSEED:HUMANS (default 410:0:0:12345:0)
#   AI       0 classic (default), 1 classic+
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
lbx="$1"; out="$2"; years="$3"; new="${4:-410:0:0:12345:0}"; ai="${5:-0}"
bin="${OOM_BIN:-$root/target/1oom/src/1oom_cmdline}"
mkdir -p "$out"
rm -f "$out"/1oom_save_*.bin
if [ ! -f "$lbx/RESEARCH.LBX" ]; then
  echo "no RESEARCH.LBX in $lbx: writing one from Age of Orion's tech tables" >&2
  (cd "$root" && cargo run --quiet --release -p aoo-harness -- research-lbx "$lbx/RESEARCH.LBX")
fi
OOM_HARNESS_YEARS="$years" "$bin" -cro -nolog -user "$out" -data "$lbx" -new "$new" -nga "$ai" -skipintro < /dev/null > "$out/1oom.txt" 2>&1 || true
ls "$out"/1oom_save_*.bin | wc -l
